    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "student_id": 16,
    "date": "2026-05-03T17:21:18",
    "status": "Leave",
    "batch_id": 16,
    "remarks": "architecto",
    "marked_by": 16
};

fetch(url, {
    method: "POST",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>


